#!/usr/bin/env node
// LZP-107 — the DMG background is a picture; the icon positions are numbers in a JSON
// file. Nothing connects them, so they drift silently: someone widens the window, the
// arrow now points at empty space, and the only way to notice is to build a release and
// look at it. This script is that connection.
//
// It asserts that four sources agree:
//   assets/dmg/background.svg      viewBox      == the window size
//   src-tauri/tauri.conf.json      dmg geometry == the drop-well the art paints
//   scripts/make-dmg.sh            constants    == the same, for the Rust-free path
//   assets/dmg/window-front.svg    label anchors== the icon centres, +40/+58 for chrome
//
// Zero dependencies, no XML parser: the handful of values it needs are matched directly.
// Run: node .github/scripts/check-dmg-geometry.mjs
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const read = (p) => readFileSync(join(ROOT, p), 'utf8');
const problems = [];
const fail = (m) => problems.push(m);

// ── the source of truth ────────────────────────────────────────────────────────
const conf = JSON.parse(read('src-tauri/tauri.conf.json'));
const dmg = conf?.bundle?.macOS?.dmg;
if (!dmg) {
  fail('src-tauri/tauri.conf.json has no bundle.macOS.dmg — the DMG would be built with '
     + "Tauri's defaults: no background, no positions, and story 22.1's designed window is gone.");
} else {
  const { width: W, height: H } = dmg.windowSize ?? {};
  const app = dmg.appPosition ?? {};
  const folder = dmg.applicationFolderPosition ?? {};

  if (dmg.background !== 'dmg/background.tiff') {
    fail(`bundle.macOS.dmg.background is "${dmg.background}", expected "dmg/background.tiff" `
       + '(generated by scripts/build-release-assets.sh). A hidpi TIFF is what makes the '
       + 'background crisp on a Retina display; a bare @2x PNG renders at twice the size.');
  }

  // ── the artwork ──────────────────────────────────────────────────────────────
  const svg = read('assets/dmg/background.svg');
  const vb = svg.match(/viewBox="0 0 (\d+) (\d+)"/);
  if (!vb) fail('assets/dmg/background.svg has no parseable viewBox.');
  else if (+vb[1] !== W || +vb[2] !== H) {
    fail(`background.svg is ${vb[1]}x${vb[2]} but the DMG window is ${W}x${H}. Finder does not `
       + 'scale a background: the art would be cropped or would leave a bare strip.');
  }

  // The drop well must actually sit under the folder icon, and be big enough to hold a
  // 128pt icon plus the label Finder draws beneath it.
  const well = svg.match(/<rect x="(\d+)" y="(\d+)" width="(\d+)" height="(\d+)" rx="\d+"\s*\n\s*fill="#ffffff"/);
  if (!well) fail('assets/dmg/background.svg: cannot find the dashed drop-well rect.');
  else {
    const [x, y, w, h] = well.slice(1).map(Number);
    const cx = x + w / 2;
    if (Math.abs(cx - folder.x) > 6) {
      fail(`the drop well is centred at x=${cx} but applicationFolderPosition.x is ${folder.x}. `
         + 'The dashed frame would sit next to the folder instead of around it.');
    }
    if (y > folder.y - 64 || y + h < folder.y + 64 + 24) {
      fail(`the drop well spans y ${y}..${y + h}; a 128pt icon centred at y=${folder.y} spans `
         + `${folder.y - 64}..${folder.y + 64} and Finder's label runs ~24px below that. `
         + 'The frame would clip the icon or cut through its label.');
    }
  }

  // The arrow must end before the well and start after the app icon.
  const arrow = svg.match(/<rect x="(\d+)" y="\d+" width="(\d+)" height="\d+" rx="8"\/>/);
  if (arrow) {
    const start = +arrow[1], end = start + +arrow[2] + 34; // + the arrowhead
    if (start < app.x + 64) fail(`the arrow starts at x=${start}, under the app icon (which ends at x=${app.x + 64}).`);
    if (end > folder.x - 64) fail(`the arrow ends at x=${end}, past the folder icon (which starts at x=${folder.x - 64}).`);
  }

  // ── the Rust-free builder ────────────────────────────────────────────────────
  const sh = read('scripts/make-dmg.sh');
  const num = (name) => {
    const m = sh.match(new RegExp(`^${name}=(\\d+)`, 'm'));
    return m ? +m[1] : null;
  };
  for (const [name, want] of [['WIN_W', W], ['WIN_H', H], ['APP_X', app.x], ['APP_Y', app.y],
                              ['FOLDER_X', folder.x], ['FOLDER_Y', folder.y]]) {
    const got = num(name);
    if (got !== want) {
      fail(`scripts/make-dmg.sh has ${name}=${got}, tauri.conf.json says ${want}. The DMG you `
         + 'can build and look at here would stop matching the one CI ships — which is the '
         + 'only reason building one here is worth anything.');
    }
  }

  // ── the e-mail illustration ──────────────────────────────────────────────────
  // window-front.svg draws the item labels; the chrome offsets the body by (40, 58).
  const front = read('assets/dmg/window-front.svg');
  const labels = [...front.matchAll(/<text x="(\d+)" y="\d+">([^<]+)<\/text>/g)].map((m) => +m[1]);
  for (const [want, got] of [[app.x + 40, labels[0]], [folder.x + 40, labels[1]]]) {
    if (got !== want) {
      fail(`assets/dmg/window-front.svg label anchored at x=${got}, expected ${want} `
         + '(icon centre + the 40px window chrome inset). The invitation e-mail would show '
         + 'labels that do not line up with the icons.');
    }
  }
}

if (problems.length) {
  console.error('DMG geometry check FAILED\n');
  for (const p of problems) console.error('  ✗ ' + p + '\n');
  process.exit(1);
}
console.log('DMG geometry OK — artwork, tauri.conf.json, make-dmg.sh and the e-mail illustration agree.');
